// Builds one injectable script from the vendored parser files and writes it
// out as a TypeScript string module for the mobile app.
//
//   node shared/vendor/build-parser-bundle.mjs
//
// The bundle defines window.shelfParse(html, url), which parses the HTML into a
// detached document (no page scripts run), runs Readability then Turndown, and
// posts the result back through ReactNativeWebView.postMessage.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, '..', '..');

const read = (p) => readFileSync(join(here, p), 'utf8');

const readability = read('readability-0.6.0/Readability.js');
const readerable = read('readability-0.6.0/Readability-readerable.js');
const turndown = read('turndown-7.2.4/turndown.browser.umd.js');
const runner = read('parser-runner.js');

// Plain concatenation at top level: Readability declares global functions and
// the Turndown UMD attaches to `this`, which is window in an injected script.
const bundle = [readability, readerable, turndown, runner, 'true;'].join('\n;\n');

const out = join(repo, 'apps', 'mobile', 'src', 'parser', 'bundle.generated.ts');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  '// Generated by shared/vendor/build-parser-bundle.mjs. Do not edit.\n' +
    `export const PARSER_BUNDLE = ${JSON.stringify(bundle)};\n`,
);
console.log(`wrote ${out} (${bundle.length} chars)`);
